type Role='admin'|'landlord'|'manager'|'tenant';
type User={id:string;name:string;email:string;phone?:string;avatar_url?:string;password:string;role:Role;orgId:string;propertyId?:string;unit?:string;welfare:'Good'|'Needs attention'|'Urgent'};
type Unit={id:string;name:string;description:string;tenantId?:string;rent:number};
type Property={id:string;orgId:string;name:string;address:string;image:string;units:Unit[]};
type Org={id:string;name:string;ownerId:string;inviteManager:string;inviteTenant:string};
type Payment={id:string;tenantId:string;amount:number;due:string;status:'Paid'|'Pending review'|'Overdue'|'Due soon';method:string};
type Cashflow={id:string;landlordId:string;orgId:string;paymentId:string;tenantId:string;amount:number;type:'Rent';status:'Recorded'|'Pending review';timestamp:string;method:string};
type Message={id:string;from:string;to:string;text:string;time:string};
type Ticket={id:string;tenantId:string;title:string;category:string;status:'Open'|'In progress'|'Resolved';priority:'Low'|'Medium'|'High'};
type PhoneCountry={key:string;name:string;code:string};
type CountryDialData={name?:{common?:string};cca2?:string;idd?:{root?:string;suffixes?:string[]}};

const makeToken=()=>Math.random().toString(36).slice(2,10);
const makeInviteCode=(role:'manager'|'tenant',orgs:Org[])=>{let code:string;do{const bytes=crypto.getRandomValues(new Uint8Array(5));const suffix=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('').toUpperCase();code=`NT-${role==='manager'?'MGR':'TEN'}-${suffix}`}while(orgs.some(org=>org.inviteManager===code||org.inviteTenant===code));return code};
